// Parity of the Swift core with spectra-lab (port-plan.md §4): one test per category of
// Fixtures/vectors.json (11,746 cases generated by spectra-lab/tests/parity/generate.mjs), plus
// coverage, the independent reference values of spectra-lab's own suite and the native
// extensions. The comparisons live in ParityVectors.swift, shared with Tools/check-core.sh.
import XCTest

@testable import Spectra

final class CoreParityTests: XCTestCase {
  private enum FixtureError: Error, CustomStringConvertible {
    case missing(String)
    var description: String {
      switch self {
      case .missing(let bundle): "vectors.json is not in the test bundle \(bundle) (SpectraTests/Fixtures is a resources phase)"
      }
    }
  }

  /// Decoded once per test run (2.4 MiB, ~1 s).
  private static let vectors: Result<ParityVectors, any Error> = Result {
    let bundle = Bundle(for: CoreParityTests.self)
    guard
      let url = bundle.url(forResource: "vectors", withExtension: "json")
        ?? bundle.url(forResource: "vectors", withExtension: "json", subdirectory: "Fixtures")
    else { throw FixtureError.missing(bundle.bundlePath) }
    return try ParityVectors.load(contentsOf: url)
  }

  /// Runs one category and reports every failing comparison (the first dozen in detail).
  private func check(_ category: String, file: StaticString = #filePath, line: UInt = #line) {
    switch Self.vectors {
    case .failure(let error):
      XCTFail("cannot load vectors.json: \(error)", file: file, line: line)
    case .success(let vectors):
      assertPassed(ParityChecks.run(category, in: vectors), file: file, line: line)
    }
  }

  private func assertPassed(_ report: ParityReport, file: StaticString = #filePath, line: UInt = #line) {
    XCTAssertGreaterThan(report.cases, 0, "\(report.category): no cases", file: file, line: line)
    for message in report.messages { XCTFail(message, file: file, line: line) }
    XCTAssertEqual(
      report.failures, 0, "\(report.category): \(report.failures) of \(report.checks) comparisons failed",
      file: file, line: line)
  }

  // MARK: Vector categories (generator order)

  func testConstants() { check("constants") }
  func testTables() { check("tables") }
  func testDataTables() { check("dataTables") }
  func testConversions() { check("conversions") }
  func testBandAt() { check("bandAt") }
  func testDescribe() { check("describe") }
  func testSpectralRGB() { check("spectralRGB") }
  func testDisplayColor() { check("displayColor") }
  func testFormat() { check("format") }
  func testCrossedDetents() { check("crossedDetents") }
  func testNearestComparison() { check("nearestComparison") }
  func testJonesFields() { check("jonesFields") }
  func testEllipse() { check("ellipse") }
  func testPolarizer() { check("polarizer") }
  func testIntensity() { check("intensity") }
  func testPlanck() { check("planck") }
  func testComponents() { check("components") }
  func testPulse() { check("pulse") }
  func testLaser() { check("laser") }
  func testElectronTrajectory() { check("electronTrajectory") }
  func testOscillatorResponse() { check("oscillatorResponse") }
  func testLorentzEpsilon() { check("lorentzEpsilon") }
  func testDrude() { check("drude") }
  func testComplexIndex() { check("complexIndex") }
  func testSlab() { check("slab") }
  func testAnchorsBridge() { check("anchorsBridge") }
  func testLogLog() { check("logLog") }
  func testMedia() { check("media") }
  func testXcom() { check("xcom") }
  func testWaterAbsorption() { check("waterAbsorption") }
  func testSpecimens() { check("specimens") }
  func testWaterAlpha() { check("waterAlpha") }
  func testInSeries() { check("inSeries") }
  func testDnaAbsorbance() { check("dnaAbsorbance") }
  func testSamples() { check("samples") }
  func testHydrogenLines() { check("hydrogenLines") }
  func testHydrogenLine() { check("hydrogenLine") }
  func testLarmor() { check("larmor") }
  func testSanitize() { check("sanitize") }
  func testEditSource() { check("editSource") }
  func testTimeScale() { check("timeScale") }
  func testDeserialize() { check("deserialize") }
  func testApplyPreset() { check("applyPreset") }
  func testFieldview() { check("fieldview") }

  // MARK: Beyond the vectors

  /// Every category in the file has a test, and the case counts match `meta` (11,746 total).
  func testCoverage() throws {
    let vectors = try Self.vectors.get()
    XCTAssertEqual(vectors.meta.total, 11_746)
    XCTAssertEqual(vectors.meta.seed, 20_261_003)
    assertPassed(ParityChecks.coverage(vectors))
  }

  /// spectra-lab tests/core.test.mjs against its reference.json: NIST, CODATA, Schott,
  /// Malitson, CRC, Segelstein and DNA spectrophotometry values.
  func testReferenceValues() { assertPassed(ParityChecks.referenceValues()) }

  /// RULER_LOG_MAX = 8 (100,000 km) is opt-in; LOG_MAX stays 3 and the defaults keep parity.
  /// Also the ITU long-wave sub-bands, the extended λ dial and NMR at any field.
  func testNativeExtensions() { assertPassed(ParityChecks.nativeExtensions()) }

  /// Display/SpectrumDisplay.swift (readout rows, tuner, lab, prism, sound pitch) against values
  /// printed by Node from spectra-lab's own functions.
  func testDisplay() { assertPassed(ParityChecks.display()) }

  /// Edge inputs (NaN, ±∞, 0, negative, subnormal, huge) never trap; negative trajectory steps,
  /// a stray `active`, an empty source list and non-finite fields in `serialized()` are handled.
  func testRobustness() { assertPassed(ParityChecks.robustness()) }

  /// Worked values for the long-wave ruler marks (λ = c/f), stated directly.
  func testLongWaveLandmarks() {
    let marks = Dictionary(uniqueKeysWithValues: Spectrum.longWaveLandmarks.map { ($0.id, $0.lambda) })
    // Water protons at 50 µT: γ′p·B = 42.576385 MHz/T · 50 µT = 2,128.82 Hz (gyre-integration.md §4.1).
    XCTAssertEqual(marks["earthNMR"] ?? 0, 140_825.70, accuracy: 0.01)
    XCTAssertEqual(marks["mains60"] ?? 0, 4_996_540.97, accuracy: 0.01)
    XCTAssertEqual(marks["mains50"] ?? 0, 5_995_849.16, accuracy: 0.01)
    XCTAssertEqual(marks["schumann"] ?? 0, 38_287_670.24, accuracy: 0.01)
  }

  /// JS-exact formatting spot checks: binary ties round away from zero, as V8 does.
  func testFormattingTies() {
    XCTAssertEqual(JSFormat.toFixed(0.125, 2), "0.13")
    XCTAssertEqual(JSFormat.toFixed(2.5, 0), "3")
    XCTAssertEqual(JSFormat.toFixed(10.25, 1), "10.3")
    XCTAssertEqual(JSFormat.toFixed(100.5, 0), "101")
    XCTAssertEqual(JSFormat.toFixed(1.005, 2), "1.00")
    XCTAssertEqual(JSFormat.toFixed(1e21, 2), "1e+21")
    XCTAssertEqual(JSFormat.toPrecision(1.23e-7, 3), "1.23e-7")
    XCTAssertEqual(JSFormat.jsString(4.33), "4.33")
    XCTAssertEqual(JSFormat.sci(9.996e5), "10.00\u{00D7}10\u{2075}")
    XCTAssertEqual(JSFormat.length(550e-9), "550 nm")
    XCTAssertEqual(JSFormat.length(1e-6), "1.00 \u{00B5}m")  // U+00B5 MICRO SIGN, not U+03BC
  }
}
